import {prepareCatalogue} from './catalogue-presentation.mjs';
export const adminRoutes=[
 ['overview','Overview','/admin/overview/',''],['conjure','Conjure','/admin/conjure/',''],
 ['inventory','Inventory / Components','/admin/?view=inventory','Catalogue'],['assemblies','Products / Assemblies','/admin/?view=assemblies','Catalogue'],['kits','Wiring Kits','/admin/wiring-kit-master/','Catalogue'],['catalogue','Catalogue Settings','/admin/catalogue-settings/','Catalogue'],
 ['orders','Orders','/admin/orders/','Sales'],
 ['articles','Luthier Hub Articles','/admin/hub-cms/','Content'],['media','Article Media','/admin/hub-media/','Content'],['news','News','/admin/site-operations/#news','Content'],['announcements','Announcements','/admin/site-operations/#announcements','Content'],
 ['operations','Site Operations','/admin/site-operations/','Operations'],['destinations','Commercial / eBay','/admin/site-operations/#commercial-destinations','Operations'],['maintenance','Settings & maintenance','/admin/?view=maintenance','System'],['email','Email Preview','/admin/email-preview/','System']
].map(([id,label,href,group])=>({id,label,href,group}));
export const workspaceDescriptions={overview:'What needs attention and where to go next.',inventory:'Manage components, availability and shared stock.',assemblies:'Manage product assemblies and wiring kit definitions.',kits:'Plan components, costs and production without reserving stock.',catalogue:'Manage catalogue labels and reusable options.',orders:'Manage customer orders, production and dispatch.',articles:'Structured articles, SEO, revisions and DOCX. Use Conjure for visual website editing.',media:'Approved assets and private article references.',news:'Manage drafts, publication and scheduled News.',announcements:'Review the shared announcement and its priority rules.',operations:'Manage ordering availability and schedules. Existing orders continue.',destinations:'Manage verified commercial destinations without changing direct checkout.',maintenance:'Private migration exports and occasional maintenance.',email:'Preview transactional templates without sending an email.'};
export function workspaceFor(location){const p=location.pathname,q=new URLSearchParams(location.search);if(p==='/admin/'||p==='/admin/index.html')return q.get('view')==='assemblies'?'assemblies':q.get('view')==='maintenance'?'maintenance':'inventory';if(p.startsWith('/admin/site-operations/'))return {'#news':'news','#announcements':'announcements','#commercial-destinations':'destinations'}[location.hash]||'operations';return adminRoutes.find(r=>new URL(r.href,'https://site.test').pathname===p)?.id||(p.startsWith('/admin/orders/')?'orders':'overview');}
export function uiNode(d,tag,text,className){const n=d.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;}
export function statusBadge(d,text,tone='neutral'){const n=uiNode(d,'span',text,'admin-badge');n.dataset.tone=tone;return n;}
export function mountAdminShell(d,signOut){const path=d.location?.pathname||'';if(path.startsWith('/admin/conjure/'))return null;const main=d.querySelector('main:not(.admin-access-gate)');if(!main)return null;
 if(d.querySelector('[data-admin-topbar]')){d.querySelector('[data-admin-session]').append(signOut);return d.querySelector('[data-admin-topbar]');}
 d.body.dataset.adminApp='v2';main.classList.add('admin-main');if(!main.id)main.id='main';
 d.querySelectorAll('body > .site-header,body > #mobile-nav,body > footer,.admin-workspaces,.admin-navigation,nav.admin-tabs').forEach(n=>n.remove());
 const css=d.createElement('link');css.rel='stylesheet';const url=new URL('./application.css',import.meta.url);url.search=new URL(import.meta.url).search;css.href=url.href;css.dataset.adminStyles='v2';d.head.append(css);
 const top=uiNode(d,'header',undefined,'admin-app-topbar');top.dataset.adminTopbar='true';const toggle=uiNode(d,'button','Menu','admin-icon-button');toggle.type='button';toggle.setAttribute('aria-controls','admin-sidebar');toggle.setAttribute('aria-expanded','false');toggle.dataset.adminMenu='true';const brand=uiNode(d,'a','APPARITION ADMIN','admin-app-brand');brand.href='/admin/overview/';const session=uiNode(d,'div',undefined,'admin-app-session');session.dataset.adminSession='true';const account=uiNode(d,'a','Account');account.href='/account/';account.target='_blank';account.rel='noopener';session.append(account,signOut);top.append(toggle,brand,session);
 const sidebar=uiNode(d,'aside',undefined,'admin-app-sidebar');sidebar.id='admin-sidebar';const nav=uiNode(d,'nav');nav.setAttribute('aria-label','Admin workspaces');let group=null;
 for(const r of adminRoutes){if(r.group&&r.group!==group){group=r.group;const h=uiNode(d,'h2',group,'admin-nav-group');nav.append(h);}const link=uiNode(d,'a',r.label,'admin-nav-item');link.href=r.href;link.dataset.workspace=r.id;if(['inventory','assemblies','orders','kits'].includes(r.id))link.dataset.adminDestination=r.id==='kits'?'master':r.id;if(r.id==='conjure')link.classList.add('admin-conjure-entry');nav.append(link);}sidebar.append(nav);main.before(top,sidebar);
 let header=main.querySelector('.admin-title');if(!header){header=uiNode(d,'div',undefined,'admin-title');const heading=main.querySelector('h1')||uiNode(d,'h1','Workspace');header.append(heading);main.prepend(header);}header.classList.add('admin-page-header');header.querySelector('.eyebrow')?.remove();main.querySelector(':scope > .eyebrow')?.remove();const description=uiNode(d,'p',undefined,'admin-page-description');description.dataset.workspaceDescription='true';header.after(description);
 prepareCatalogue(d);
 const paint=()=>{const id=workspaceFor(d.location),route=adminRoutes.find(r=>r.id===id);for(const a of nav.querySelectorAll('a')){if(a.dataset.workspace===id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}description.textContent=workspaceDescriptions[id]||'';if(path.includes('/site-operations/')&&route)header.querySelector('h1').textContent=route.label;};paint();d.defaultView.addEventListener('hashchange',paint);
 const close=()=>{d.body.removeAttribute('data-admin-menu-open');toggle.setAttribute('aria-expanded','false');};toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));d.body.toggleAttribute('data-admin-menu-open',open);});sidebar.addEventListener('click',e=>{if(e.target.closest('a'))close();});d.addEventListener('keydown',e=>{if(e.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){close();toggle.focus();}});
 return top;
}
